settings.customCSS:
/* ============================================================
   ESTILO ACTUAL CON BORDES CUADRADOS
   Mantiene la esencia visual pero con bordes rectos
   Solo conserva círculos donde es funcionalmente necesario
   ============================================================ */

/* ============================================================
   1. ELIMINAR BORDES REDONDEADOS (EXCEPTO CÍRCULOS ESENCIALES)
   ============================================================ */

/* Eliminar bordes redondeados de TODOS los elementos por defecto */
* {
    border-radius: 0 !important;
}

/* EXCEPCIONES: Elementos que DEBEN ser circulares por función */
/* Avatares, indicadores de estado, botones circulares específicos */

/* Avatares de perfil (fotos de persona) */
.w-8.h-8.rounded-full,
.w-10.h-10.rounded-full,
.w-12.h-12.rounded-full,
.w-14.h-14.rounded-full,
.w-16.h-16.rounded-full,
.avatar,
[class*="rounded-full"]:has(img),
[class*="rounded-full"]:has(svg[data-avatar]) {
    border-radius: 9999px !important;
}

/* Indicadores de estado circulares (puntos de estado) */
.w-2.h-2.rounded-full,
.w-3.h-3.rounded-full,
.w-1.5.h-1.5.rounded-full,
[class*="rounded-full"]:has(.w-2),
[class*="rounded-full"]:has(.w-1\\.5) {
    border-radius: 9999px !important;
}

/* Círculos de progreso (circular-progress) */
.circular-progress,
[class*="circular-progress"] {
    border-radius: 9999px !important;
}

/* Botones circulares de acción (FAB) */
.w-8.h-8.rounded-full:has(.material-symbols-outlined),
.w-10.h-10.rounded-full:has(.material-symbols-outlined),
.w-12.h-12.rounded-full:has(.material-symbols-outlined),
button.w-8.h-8.rounded-full,
button.w-10.h-10.rounded-full,
button.w-12.h-12.rounded-full {
    border-radius: 9999px !important;
}

/* Botones de ayuda y acciones flotantes */
[class*="rounded-full"]:has(.material-symbols-outlined),
[class*="rounded-full"]:has(span.material-symbols-outlined) {
    border-radius: 9999px !important;
}

/* Badges con forma circular (contadores) */
[class*="rounded-full"]:has(.text-[10px]),
[class*="rounded-full"]:has(.text-xs),
[class*="rounded-full"]:has(span.font-bold) {
    border-radius: 9999px !important;
}

/* ============================================================
   2. RESTAURAR EL ESTILO ORIGINAL (SIN BORDES REDONDEADOS)
   ============================================================ */

/* Restaurar colores y estilos originales */
:root {
    --dds-primary: #000000;
    --dds-accent: #d4a853;
    --dds-surface: #f7f9fb;
    --dds-surface-card: #ffffff;
    --dds-border: #c6c6cd;
    --dds-border-light: #e0e3e5;
    --dds-text: #191c1e;
    --dds-text-secondary: #45464d;
}

/* ============================================================
   3. TARJETAS Y CONTENEDORES (SIN REDONDEO)
   ============================================================ */

.bg-white,
.bg-surface-container-lowest,
.bg-surface-container-low,
.bg-surface-container,
.bg-surface-container-high,
.bg-surface-container-highest,
.border,
.border-outline-variant {
    border-radius: 0 !important;
}

/* Tarjetas con sombra */
.shadow-sm,
.shadow-md,
.shadow-lg,
.shadow-xl {
    border-radius: 0 !important;
}

/* ============================================================
   4. BOTONES (SIN REDONDEO)
   ============================================================ */

button,
.btn,
[role="button"],
input[type="submit"],
input[type="button"] {
    border-radius: 0 !important;
}

/* Botones con iconos - mantener circulares SOLO si son FAB */
button.w-8.h-8:has(.material-symbols-outlined):not(.btn-primary):not(.btn-secondary),
button.w-10.h-10:has(.material-symbols-outlined):not(.btn-primary):not(.btn-secondary),
button.p-2:has(.material-symbols-outlined):not(.btn-primary):not(.btn-secondary) {
    border-radius: 9999px !important;
}

/* ============================================================
   5. INPUTS Y FORMULARIOS (SIN REDONDEO)
   ============================================================ */

input,
select,
textarea,
[contenteditable="true"] {
    border-radius: 0 !important;
}

/* ============================================================
   6. TABLAS (SIN REDONDEO)
   ============================================================ */

table,
table * {
    border-radius: 0 !important;
}

/* ============================================================
   7. MODALES Y OVERLAYS (SIN REDONDEO)
   ============================================================ */

.bg-black\/50,
.bg-white.rounded-3xl,
.bg-white.rounded-2xl,
.bg-white.rounded-xl,
.modal,
.popup {
    border-radius: 0 !important;
}

/* ============================================================
   8. KANBAN Y TABLEROS (SIN REDONDEO)
   ============================================================ */

.kanban-column,
.kanban-column * {
    border-radius: 0 !important;
}

/* ============================================================
   9. BADGES Y ETIQUETAS (SIN REDONDEO EXCEPTO CONTADORES)
   ============================================================ */

/* Badges normales - sin redondeo */
.px-2.py-0\.5,
.px-3.py-1,
.px-2.py-1,
.badge,
.tag {
    border-radius: 0 !important;
}

/* Badges que son contadores numéricos - mantener circulares */
.px-2.py-0\.5.rounded-full:has(.text-[10px]),
.px-2.py-0\.5.rounded-full:has(.text-xs),
.bg-error.text-white.px-2.py-0\.5.rounded-full,
.bg-emerald-100.text-emerald-800.px-2.py-0\.5.rounded-full,
.bg-amber-100.text-amber-800.px-2.py-0\.5.rounded-full {
    border-radius: 9999px !important;
}

/* ============================================================
   10. PROGRESS BARS (SIN REDONDEO)
   ============================================================ */

.h-1\.5,
.h-1,
.h-2,
.progress,
[class*="h-"]:has([class*="bg-"]) {
    border-radius: 0 !important;
}

[class*="bg-"]:has(.h-full) {
    border-radius: 0 !important;
}

/* ============================================================
   11. SIDEBAR (SIN REDONDEO)
   ============================================================ */

aside,
aside * {
    border-radius: 0 !important;
}

.nav-item {
    border-radius: 0 !important;
}

/* ============================================================
   12. HEADER (SIN REDONDEO)
   ============================================================ */

header,
header * {
    border-radius: 0 !important;
}

/* ============================================================
   13. SCROLLBAR (SIN REDONDEO)
   ============================================================ */

::-webkit-scrollbar {
    border-radius: 0 !important;
}

::-webkit-scrollbar-thumb {
    border-radius: 0 !important;
}

::-webkit-scrollbar-track {
    border-radius: 0 !important;
}

/* ============================================================
   14. IMÁGENES Y LOGOS (SIN REDONDEO)
   ============================================================ */

img,
svg {
    border-radius: 0 !important;
}

/* Mantener circular SOLO si es un avatar de persona */
img[class*="rounded-full"],
svg[class*="rounded-full"] {
    border-radius: 9999px !important;
}

/* ============================================================
   15. SELECTORES ESPECÍFICOS DE TU APP
   ============================================================ */

/* Tarjetas de estadísticas */
.bg-white.border.border-outline-variant.rounded-2xl {
    border-radius: 0 !important;
}

/* Tarjetas de personal */
.bg-white.border.border-outline-variant.p-4.rounded-lg {
    border-radius: 0 !important;
}

/* Contenedores de kanban */
.bg-surface-container-low.p-4.border-b-4 {
    border-radius: 0 !important;
}

/* Tablas */
.bg-white.border.border-outline-variant.rounded-xl {
    border-radius: 0 !important;
}

/* Formularios */
.bg-surface-container-low.p-8.rounded-3xl {
    border-radius: 0 !important;
}

/* Modales */
.bg-white.rounded-3xl {
    border-radius: 0 !important;
}

/* ============================================================
   16. EXCEPCIONES ESPECIALES - ELEMENTOS QUE DEBEN SER CÍRCULOS
   ============================================================ */

/* Avatares en el ranking */
.w-8.h-8.rounded-full.bg-primary.text-white {
    border-radius: 9999px !important;
}

/* Indicadores de estado en la barra lateral */
.w-2.h-2.rounded-full {
    border-radius: 9999px !important;
}

/* Botones de ayuda flotantes */
button.p-2.text-primary.hover\:bg-primary\/10.rounded-full {
    border-radius: 9999px !important;
}

/* Botones de toggle en la barra lateral */
button.p-2.hover\:bg-surface-container.rounded-lg {
    border-radius: 0 !important;
}

/* ============================================================
   17. MANTENER EL ESTILO ORIGINAL DE TU APP
   ============================================================ */

/* Colores originales */
.bg-primary {
    background-color: var(--dds-primary) !important;
}

.text-primary {
    color: var(--dds-primary) !important;
}

.border-primary {
    border-color: var(--dds-primary) !important;
}

/* Sombras originales */
.shadow-sm {
    box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05) !important;
}

.shadow-md {
    box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1) !important;
}

.shadow-lg {
    box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1) !important;
}

.shadow-xl {
    box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1) !important;
}

/* Transiciones suaves */
* {
    transition: all 0.15s ease !important;
}

/* ============================================================
   18. MEDIA QUERIES - MANTENER CONSISTENCIA
   ============================================================ */

@media print {
    * {
        border-radius: 0 !important;
    }

    .w-8.h-8.rounded-full,
    .w-10.h-10.rounded-full,
    .w-12.h-12.rounded-full {
        border-radius: 9999px !important;
    }
}
